CREATE OR REPLACE FUNCTION calc_effective_leverage(
    p_leverage TEXT,
    p_position_value NUMERIC,
    p_balance NUMERIC
)
RETURNS NUMERIC AS $$
BEGIN
    RETURN CAST(p_leverage AS NUMERIC) * (p_position_value / p_balance);
END;
$$ LANGUAGE plpgsql;

